<template><ForgeDialog title="Code library" description="Save reusable snippets and find them quickly across projects." eyebrow="WORKSPACE / CODE" wide @close="emit('close')"><div class="library-panel"><div class="library-toolbar"><input v-model="query" placeholder="Search snippets" /><select v-model="language"><option value="all">All languages</option><option v-for="lang in languages" :key="lang" :value="lang">{{ lang }}</option></select><button class="primary-button" @click="newSnippet">New snippet</button></div><div class="library-layout"><div class="snippet-list"><button v-for="snippet in filtered" :key="snippet.id" :class="{active:snippet.id===selected?.id}" @click="select(snippet)"><b>{{ snippet.name }}</b><small>{{ snippet.language }} · {{ snippet.group }}</small></button><p v-if="!filtered.length" class="empty-copy">No snippets yet.</p></div><div class="snippet-editor"><template v-if="selected"><div class="editor-fields"><input v-model="selected.name" placeholder="Snippet name" /><input v-model="selected.group" placeholder="Group" /><select v-model="selected.language"><option v-for="lang in languages" :key="lang">{{ lang }}</option></select></div><textarea v-model="selected.value" spellcheck="false" /><div class="detail-actions"><button class="action-button action-button--danger" @click="remove">Delete</button><button class="primary-button" @click="save">Save snippet</button></div></template><p v-else class="empty-copy">Select a snippet or create one.</p></div></div></div></ForgeDialog></template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import ForgeDialog from './ForgeDialog.vue'
type Snippet={id:string;name:string;group:string;language:string;value:string}; const emit=defineEmits<{close:[]}>(); const languages=['javascript','typescript','python','php','go','java','rust','shell','sql','json','markdown']; const snippets=reactive<Snippet[]>([]); const selected=ref<Snippet>(); const query=ref(''); const language=ref('all'); const filtered=computed(()=>snippets.filter(s=>(language.value==='all'||s.language===language.value)&&(s.name+' '+s.group+' '+s.value).toLowerCase().includes(query.value.toLowerCase()))); const persist=()=>localStorage.setItem('pqt-forge-code-library',JSON.stringify(snippets)); const select=(item:Snippet)=>{selected.value=item}; const newSnippet=()=>{const item=reactive({id:crypto.randomUUID(),name:'Untitled snippet',group:'General',language:'typescript',value:''});snippets.unshift(item);selected.value=item}; const save=()=>persist(); const remove=()=>{if(!selected.value)return;const index=snippets.findIndex(s=>s.id===selected.value?.id);if(index>=0)snippets.splice(index,1);selected.value=undefined;persist()}; onMounted(()=>{try{snippets.push(...JSON.parse(localStorage.getItem('pqt-forge-code-library')||'[]'))}catch{}}); watch(snippets,persist,{deep:true})
</script>
<style scoped>.library-panel{display:grid;gap:12px}.library-toolbar{display:flex;gap:8px}.library-toolbar input,.library-toolbar select,.editor-fields input,.editor-fields select{padding:9px 10px;color:var(--pqt-text);background:var(--pqt-canvas);border:1px solid var(--pqt-border-strong);border-radius:7px;font:11px var(--pqt-font-mono)}.library-toolbar input{flex:1}.library-layout{display:grid;grid-template-columns:230px 1fr;gap:12px;min-height:410px}.snippet-list{display:grid;align-content:start;gap:5px;overflow:auto}.snippet-list button{text-align:left;padding:9px;border:1px solid var(--pqt-border);border-radius:7px;background:transparent;color:var(--pqt-text);cursor:pointer}.snippet-list button.active{border-color:var(--pqt-accent);background:#1b3536}.snippet-list button b,.snippet-list button small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.snippet-list button small{margin-top:4px;color:var(--pqt-text-muted);font-size:10px}.snippet-editor{display:grid;grid-template-rows:auto 1fr auto;gap:8px}.editor-fields{display:grid;grid-template-columns:1fr 1fr 130px;gap:7px}.snippet-editor textarea{width:100%;min-height:300px;resize:none;padding:12px;color:var(--pqt-text);background:var(--pqt-canvas);border:1px solid var(--pqt-border-strong);border-radius:7px;font:11px/1.5 var(--pqt-font-mono)}</style>
